package dev.rodrigo.nfclab; import android.nfc.cardemulation.HostApduService; import android.os.Bundle; import java.nio.charset.StandardCharsets; import java.util.Arrays; public class DemoHostApduService extends HostApduService { private static final byte[] SELECT={(byte)0x00,(byte)0xA4,(byte)0x04,(byte)0x00,(byte)0x07,(byte)0xF0,0x01,0x02,0x03,0x04,0x05,0x06}; private static final byte[] OK={(byte)0x90,0x00}; private static final byte[] NO={(byte)0x6A,(byte)0x82}; @Override public byte[] processCommandApdu(byte[] apdu,Bundle extras){if(apdu!=null&&apdu.length>=SELECT.length&&Arrays.equals(Arrays.copyOf(apdu,SELECT.length),SELECT)){byte[] msg="HELLO-NFC-LAB".getBytes(StandardCharsets.UTF_8);byte[] out=Arrays.copyOf(msg,msg.length+2);out[out.length-2]=OK[0];out[out.length-1]=OK[1];return out;}return NO;} @Override public void onDeactivated(int reason){} }